class Solution(object):
    def greatestLetter(self, s):
        """
        :type s: str
        :rtype: str
        """
        u_flag = [False] * 26
        l_flag = [False] * 26
        for c in s:
            if c.isupper():
                u_flag[ord(c) - ord('A')] = True
            elif c.islower():
                l_flag[ord(c) - ord('a')] = True
        for i in range(25, -1, -1):
            if u_flag[i] and l_flag[i]:
                return chr(ord('A') + i)
        return ""
